function urlB64(s:string){ const pad='='.repeat((4-s.length%4)%4); const base=(s+pad).replace(/-/g,'+').replace(/_/g,'/'); const raw=atob(base); const arr=new Uint8Array(raw.length); for(let i=0;i<raw.length;i++) arr[i]=raw.charCodeAt(i); return arr }
const AZUL='#0B4DA2', MARINHO='#0A2F6B', ROSA='#E91E8C', VERDE='#58B531', CLARO='#EAF2FF'
