 const [recebimento,setRecebimento]=useState<'entrega'|'retirada'>('entrega'); const [pagamento,setPagamento]=useState<any>('pix')
 const [toast,setToast]=useState(''); const [loginUser,setLoginUser]=useState(''); const [loginPass,setLoginPass]=useState('')
 const [novoProd,setNovoProd]=useState({nome:'',categoria:'Sorvetes 1 Litro',embalagem:'Pote 1 Litro',preco:'19.90',estoque:'0'})
