 const [ultimoAcesso,setUltimoAcesso]=useState<any>(null)
 const [manualRev,setManualRev]=useState('r1'); const [manualCart,setManualCart]=useState<Record<string,number>>({}); const [manualRec,setManualRec]=useState<'entrega'|'retirada'>('entrega'); const [manualPag,setManualPag]=useState<any>('pix')
 const [modoCadastro,setModoCadastro]=useState(false); const [cad,setCad]=useState({nome:'',negocio:'',telefone:'',doc:'',endereco:'',email:'',senha:''})
 const [novaSenha,setNovaSenha]=useState(''); const [confSenha,setConfSenha]=useState(''); const [modoRecuperar,setModoRecuperar]=useState(false); const [senhaAberta,setSenhaAberta]=useState(false)
 const statusAntigos=React.useRef<Record<string,string>>({}); const qtdPedidosAdmin=React.useRef<number|null>(null)
 const pixAntigos=React.useRef<Record<string,string>>({}); const qtdCadastros=React.useRef<number|null>(null); const qtdPixAdmin=React.useRef<number|null>(null)
 const [pushPrefs,setPushPrefs]=useState<any>(null);
 const [novoInsumo,setNovoInsumo]=useState({nome:'',unidade:'kg',minimo:'0'})
 const [compraIns,setCompraIns]=useState<Record<string,{qtd:string;valor:string}>>({})
 const [produzirQtd,setProduzirQtd]=useState<Record<string,string>>({})
 const [fichaAlvo,setFichaAlvo]=useState<string>(''); const [pushPronto,setPushPronto]=useState(false); const [pushPerm,setPushPerm]=useState('default'); const [pushServidor,setPushServidor]=useState<boolean|null>(null)
 const [perfilForm,setPerfilForm]=useState<any>(null)

 const [remoteOk,setRemoteOk]=useState(false)
 useEffect(()=>{try{const d=localStorage.getItem('extrabom_db_v3'); if(d) setDb(JSON.parse(d)); const ss=localStorage.getItem('extrabom_session'); if(ss && !supabase) setSession(JSON.parse(ss))}catch(e){} setLoaded(true)},[])
 useEffect(()=>{if(loaded) localStorage.setItem('extrabom_db_v3',JSON.stringify(db))},[db,loaded])
 useEffect(()=>{ setOnline(navigator.onLine); const on=()=>setOnline(true), off=()=>setOnline(false); window.addEventListener('online',on); window.addEventListener('offline',off); if('serviceWorker' in navigator){ navigator.serviceWorker.register('/sw.js').catch(()=>{}) } return ()=>{ window.removeEventListener('online',on); window.removeEventListener('offline',off) } },[])
 useEffect(()=>{ if(!session) return; try{ const k='extrabom_push_prefs:'+session.role+':'+(session.revendedorId||''); const salvas=localStorage.getItem(k); setPushPrefs(salvas?{...prefsPadraoNotif(session.role),...JSON.parse(salvas)}:prefsPadraoNotif(session.role)) }catch(e){ setPushPrefs(prefsPadraoNotif(session.role)) } },[session?.role,session?.revendedorId])
 useEffect(()=>{ try{ if(typeof Notification!=='undefined') setPushPerm(Notification.permission) }catch(e){} if(!session) return; (async()=>{ try{ const r=await fetch('/api/push/chave'); const j=await r.json(); setPushServidor(!!j.ativo) }catch(e){ setPushServidor(false) } try{ if('serviceWorker' in navigator){ const reg=await navigator.serviceWorker.ready; const sub=await reg.pushManager.getSubscription(); setPushPronto(!!sub) } }catch(e){} })() },[session?.role,session?.revendedorId])
 useEffect(()=>{ if(online&&supabase&&loaded&&remoteOk){ supabase.from('app_dados').upsert({id:1,dados:db,atualizado_em:new Date().toISOString()}).then(()=>{}) } },[online])
 // SUPABASE: carrega o estado compartilhado (banco da EXTRABOM) ao abrir
 useEffect(()=>{ if(!supabase){setRemoteOk(true);return} let vivo=true; (async()=>{ try{ const {data}=await supabase.from('app_dados').select('dados').eq('id',1).maybeSingle(); if(vivo&&data&&data.dados){ let d:any=data.dados; if(d.versao!==4){ const novo=seedDB(); const antigo:Record<string,any>={}; (d.produtos||[]).forEach((x:any)=>antigo[x.id]=x); d={...d,versao:4,produtos:novo.produtos.map(np=>({...np,estoqueFisico:antigo[np.id]?.estoqueFisico??np.estoqueFisico,estoqueReservado:antigo[np.id]?.estoqueReservado??0})),revendedores:(d.revendedores||[]).map((r:any)=>({...r,precos:{}})),promocoes:novo.promocoes} } if(!Array.isArray(d.insumos)){ const sdd=seedDB(); d.insumos=sdd.insumos } if(!Array.isArray(d.movInsumos)) d.movInsumos=[]; if(!d.fichas||typeof d.fichas!=='object') d.fichas={}; setDb(d) } }catch(e){} if(vivo) setRemoteOk(true) })(); return ()=>{vivo=false} },[])
 // SUPABASE: salva cada alteracao no banco compartilhado (com pequena espera)
 useEffect(()=>{ if(!supabase||!loaded||!remoteOk) return; const t=setTimeout(()=>{ supabase.from('app_dados').upsert({id:1,dados:db,atualizado_em:new Date().toISOString()}).then(()=>{}) },700); return ()=>clearTimeout(t) },[db,loaded,remoteOk])
 // SUPABASE: atualiza a tela quando outro aparelho muda algo (a cada 12s)
 useEffect(()=>{ if(!supabase||!remoteOk) return; const iv=setInterval(async()=>{ try{ const {data}=await supabase.from('app_dados').select('dados').eq('id',1).maybeSingle(); if(data&&data.dados) setDb((prev:DB)=> JSON.stringify(prev)===JSON.stringify(data.dados)? prev : data.dados) }catch(e){} },12000); return ()=>clearInterval(iv) },[remoteOk])
 useEffect(()=>{if(!toast) return; const t=setTimeout(()=>setToast(''),3200); return ()=>clearTimeout(t)},[toast])
 // AVISOS NO APARELHO: detecta novidades quando o banco atualiza (respeita as preferencias)
 useEffect(()=>{ if(!remoteOk) return; try{
   if(session?.role==='revendedor'&&rev){ meusPedidos.forEach(pd=>{ const ant=statusAntigos.current[pd.id]; if(ant&&ant!==pd.status){ const tipoEntrega=['pronto','saiu_entrega','entregue','retirado'].includes(pd.status); notifyCelular(tipoEntrega?'pronto_entrega':'status',(tipoEntrega?'🚚 ':'📦 ')+'Pedido '+pd.numero,STATUS_LABEL[pd.status]+' • '+money(pd.total)); setToast('Pedido '+pd.numero+': '+STATUS_LABEL[pd.status]) } statusAntigos.current[pd.id]=pd.status; const antPag=pixAntigos.current[pd.id]; if(antPag&&antPag!==pd.pagSituacao&&pd.pagSituacao==='pago') notifyCelular('pix','✅ Pix confirmado','Recebemos o pagamento do pedido '+pd.numero+'.'); pixAntigos.current[pd.id]=pd.pagSituacao }) }
   if(session?.role==='admin'){
     if(qtdPedidosAdmin.current!==null&&db.pedidos.length>qtdPedidosAdmin.current){ const novo=db.pedidos[0]; notifyCelular('novo_pedido','🧾 Novo pedido recebido!',(novo?('Pedido '+novo.numero+' • '+money(novo.total)):'Abra a Central de Pedidos.')); setToast('Novo pedido recebido!') } qtdPedidosAdmin.current=db.pedidos.length
     if(qtdCadastros.current!==null&&db.revendedores.length>qtdCadastros.current){ const novo=db.revendedores[db.revendedores.length-1]; notifyCelular('novo_cadastro','📝 Cadastro em analise',(novo?novo.nome+' aguardando liberacao.':'Novo cadastro aguardando.')) } qtdCadastros.current=db.revendedores.length
     const pixPend=db.pedidos.filter(x=>x.pagSituacao==='aguardando_confirmacao').length; if(qtdPixAdmin.current!==null&&pixPend>qtdPixAdmin.current) notifyCelular('pix','💠 Pix para conferir','Um revendedor avisou que pagou. Confira no Financeiro.'); qtdPixAdmin.current=pixPend
     const baixo=db.produtos.filter(x=>disponivel(x)<=10).length; (window as any).__extrabomBaixo=(window as any).__extrabomBaixo??baixo; if(baixo>(window as any).__extrabomBaixo) notifyCelular('estoque_baixo','📦 Estoque baixo','Tem produto ficando sem estoque. Veja o Dashboard.'); (window as any).__extrabomBaixo=baixo
   }
 }catch(e){} },[db.pedidos,db.revendedores,remoteOk,pushPrefs])
 // FREEZER com app aberto: avisa 1 vez por vencimento (e 1 vez por dia se atrasado)
 useEffect(()=>{ if(session?.role!=='admin'||!pushPrefs) return; try{ const reg=JSON.parse(localStorage.getItem('extrabom_freezer_local')||'{}'); const hojeStr=new Date().toISOString().slice(0,10); db.revendedores.filter(r=>r.temFreezer).forEach(r=>{ const inf=infoReposicao(r,db.pedidos); if(inf.situacao!=='vencendo'&&inf.situacao!=='atrasado') return; const tipo=inf.situacao==='atrasado'?'freezer_atrasado':'freezer_vencendo'; const chave=inf.situacao==='atrasado'?(r.id+':atrasado:'+hojeStr):(r.id+':'+(inf.proxima?inf.proxima.toISOString().slice(0,10):'')+':'+inf.diasRestantes); if(reg[chave]) return; reg[chave]=hojeStr; notifyCelular(tipo,inf.situacao==='atrasado'?'🚨 Freezer atrasado':'🧊 Reposicao de freezer',r.nome+': '+(inf.situacao==='atrasado'?('atrasado ha '+Math.abs(inf.diasRestantes||0)+' dia(s).'):inf.diasRestantes===0?'vence HOJE.':'amanha.')) }); localStorage.setItem('extrabom_freezer_local',JSON.stringify(reg)) }catch(e){} },[db.pedidos,db.revendedores,pushPrefs,session?.role])
 const rev:Revendedor|undefined = session?.role==='revendedor' ? db.revendedores.find(r=>r.id===session.revendedorId) : undefined
