 const cartItens = useMemo(()=>{ const totalPic=Object.entries(cart).reduce((a,[id,q])=>{const pp=db.produtos.find(x=>x.id===id); return a+((pp&&pp.categoria.startsWith('Picolés')&&q>0)?q:0)},0); return Object.entries(cart).filter(([,q])=>q>0).map(([id,q])=>{const p=db.produtos.find(x=>x.id===id)!; const precoBase=p.categoria.startsWith('Picolés')?precoPicole(totalPic):(rev?precoPara(p,rev):p.precoPadrao); return {p,q,preco:precoBase}}).filter(x=>x.p) },[cart,db,rev])
 const cartTotal = cartItens.reduce((a,i)=>a+i.preco*i.q,0)
 const cartCount = cartItens.reduce((a,i)=>a+i.q,0)
 const faltaMin = rev? Math.max(0, rev.pedidoMinimo-cartTotal):0
