 // ---------- AVISOS NO CELULAR (push) ----------
 function prefsPadraoNotif(role:string){ return {novo_pedido:true,novo_cadastro:true,pix:true,freezer_vencendo:true,freezer_atrasado:true,estoque_baixo:true,status:true,pronto_entrega:true,freezer:true,promocoes:true} }
 function chavePrefsNotif(){ return 'extrabom_push_prefs:'+(session?.role||'')+':'+(session?.revendedorId||'') }
 function notifyCelular(tipo:string,titulo:string,corpo:string){ try{ if(pushPrefs&&pushPrefs[tipo]===false) return; if(typeof Notification==='undefined'||Notification.permission!=='granted') return; if('serviceWorker' in navigator){ navigator.serviceWorker.ready.then(reg=>{ try{ reg.showNotification(titulo,{body:corpo,icon:'/logo.png',badge:'/logo.png',tag:'extrabom-'+tipo+'-'+Date.now(),vibrate:[120,60,120]} as any) }catch(e){ try{ new Notification(titulo,{body:corpo,icon:'/logo.png'}) }catch(_){} } }).catch(()=>{ try{ new Notification(titulo,{body:corpo,icon:'/logo.png'}) }catch(_){} }) } else new Notification(titulo,{body:corpo,icon:'/logo.png'}) }catch(e){} }
 async function tokenPush(){ try{ if(!supabase) return null; const {data}=await supabase.auth.getSession(); return data?.session?.access_token||null }catch(e){ return null } }
 async function enviarPushRemoto(payload:any){ try{ const token=await tokenPush(); if(!token) return; await fetch('/api/push/enviar',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify(payload)}) }catch(e){} }
 async function ativarAvisosCelular(){ try{
   if(typeof Notification==='undefined'||!('serviceWorker' in navigator)||!('PushManager' in window)){ setToast('Este aparelho/navegador nao aceita esse tipo de aviso. No iPhone, instale o app (Adicionar a Tela de Inicio) e abra por ele.'); return }
   let perm=Notification.permission; if(perm!=='granted') perm=await Notification.requestPermission(); setPushPerm(perm)
   if(perm!=='granted'){ setToast('Permissao nao concedida. Ative os avisos nas configuracoes do aparelho/navegador.'); return }
   const reg=await navigator.serviceWorker.register('/sw.js').then(()=>navigator.serviceWorker.ready)
   let chave=PUSH_CHAVE_PUBLICA; try{ const r=await fetch('/api/push/chave'); const j=await r.json(); if(j.publicKey) chave=j.publicKey; setPushServidor(!!j.ativo) }catch(e){}
   let sub=await reg.pushManager.getSubscription(); if(!sub) sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlB64(chave)})
   const token=await tokenPush(); if(!token){ setToast('Avisos ligados neste aparelho! (Entre de novo para valer tambem com o app fechado.)'); setPushPronto(true); return }
   const prefs=pushPrefs||prefsPadraoNotif(session?.role||'revendedor')
   const r=await fetch('/api/push/assinar',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({subscription:sub.toJSON(),prefs,aparelho:navigator.userAgent})})
   if(!r.ok){ setToast('Nao consegui registrar este aparelho no servidor.'); return }
   setPushPronto(true); setToast(pushServidor===false?'Aparelho registrado! Falta so ligar a chave do servidor na Vercel (passo unico).':'🔔 Avisos ativados neste celular! Mesmo com o app fechado.')
 }catch(e){ setToast('Nao foi possivel ativar os avisos aqui.') } }
 async function atualizarPrefNotif(chave:string,valor:boolean){ const novas={...(pushPrefs||prefsPadraoNotif(session?.role||'revendedor')),[chave]:valor}; setPushPrefs(novas); try{ localStorage.setItem(chavePrefsNotif(),JSON.stringify(novas)) }catch(e){}
   try{ if('serviceWorker' in navigator){ const reg=await navigator.serviceWorker.ready; const sub=await reg.pushManager.getSubscription(); const token=await tokenPush(); if(sub&&token) await fetch('/api/push/assinar',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({subscription:sub.toJSON(),prefs:novas,aparelho:navigator.userAgent})}) } }catch(e){} }
 async function desativarAvisosCelular(){ try{ if('serviceWorker' in navigator){ const reg=await navigator.serviceWorker.ready; const sub=await reg.pushManager.getSubscription(); if(sub){ const token=await tokenPush(); if(token) await fetch('/api/push/assinar',{method:'DELETE',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({endpoint:sub.endpoint})}); await sub.unsubscribe() } } setPushPronto(false); setToast('Avisos desligados neste aparelho.') }catch(e){ setToast('Nao consegui desligar aqui.') } }
 async function testarAvisoCelular(){ if(!pushPronto){ await ativarAvisosCelular(); return } const token=await tokenPush(); if(!token){ notifyCelular('teste','🔔 EXTRABOM SORVETES','Teste de aviso neste aparelho.'); return } try{ const r=await fetch('/api/push/enviar',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({tipo:'teste',titulo:'🔔 EXTRABOM SORVETES',corpo:'Teste: seus avisos no celular estao funcionando!'})}); const j=await r.json(); if(j.configurado===false||j.ativo===false){ notifyCelular('teste','🔔 EXTRABOM SORVETES','Teste com o app aberto funcionou.'); setToast('Com o app aberto funciona! Para apitar com o app FECHADO, falta ligar a chave na Vercel.') } else setToast('Aviso de teste enviado! Feche o app e veja chegar.') }catch(e){ notifyCelular('teste','🔔 EXTRABOM SORVETES','Teste de aviso neste aparelho.'); setToast('Teste enviado neste aparelho.') } }


 // ---------- PEDIDO ----------
 function registrarProducao(prodId:string,qtd:number){ const prod=db.produtos.find(x=>x.id===prodId); if(!prod||qtd<=0){setToast('Informe a quantidade produzida.');return} const insumos=db.insumos||[]; const nec=insumosNecessarios([{produto:prod,qtd}],insumos,db.fichas); const faltam=nec.filter(n=>n.falta>0); if(fichaDo(prod,db.fichas).length&&faltam.length){ if(!confirm('Atencao: faltam insumos para essa producao:\n'+faltam.map(f=>'- '+f.insumo.nome+': precisa '+f.precisa.toFixed(2)+' '+f.insumo.unidade+', tem '+f.tem.toFixed(2)).join('\n')+'\n\nProduzir mesmo assim? (baixa so o que tem em estoque)')) return } const custo=custoUnitario(prod,insumos); updateDb(d=>{ const pr=d.produtos.find(x=>x.id===prodId)!; pr.estoqueFisico+=qtd; nec.forEach(n=>{ const ins=(d.insumos||[]).find(i=>i.id===n.insumo.id); if(ins) ins.estoque=Math.max(0,ins.estoque-n.precisa); d.movInsumos=d.movInsumos||[]; d.movInsumos.unshift({id:'mi'+Date.now()+n.insumo.id,insumo:n.insumo.nome,tipo:'uso',qtd:n.precisa,em:new Date().toISOString(),motivo:'Producao de '+qtd+'x '+prod.nome}) }); d.movimentos.unshift({id:'m'+Date.now(),produto:prod.nome,tipo:'entrada',qtd,em:new Date().toISOString(),motivo:'Producao registrada pelo escritorio'}); return d }); setToast('Produzido: '+qtd+'x '+prod.nome+(custo!=null?(' • custo estimado '+money(custo*qtd)+' ('+money(custo)+'/un)'):' • (sem ficha: nenhum insumo baixado)')) }
 function criarPedidoManual(){ const r=db.revendedores.find(x=>x.id===manualRev); if(!r){setToast('Escolha o revendedor.');return} const itens=Object.entries(manualCart).filter(([,q])=>q>0).map(([id,q])=>{const pr=db.produtos.find(x=>x.id===id)!; return {p:pr,q}}).filter(x=>x.p); if(!itens.length){setToast('Adicione pelo menos 1 produto.');return} const totalPic=itens.filter(x=>x.p.categoria.startsWith('Picolés')).reduce((a,x)=>a+x.q,0); const comPreco=itens.map(x=>({...x,preco:x.p.categoria.startsWith('Picolés')?precoPicole(totalPic):precoPara(x.p,r)})); const total=comPreco.reduce((a,x)=>a+x.preco*x.q,0); if(total<r.pedidoMinimo && !confirm('Total '+money(total)+' esta abaixo do minimo de '+money(r.pedidoMinimo)+' deste revendedor. Como e um atendimento da empresa, deseja lancar mesmo assim?')) return; const numero='EXT-'+new Date().getFullYear()+'-'+String(db.pedidos.length+1).padStart(4,'0'); const pedido:Pedido={id:'ped'+Date.now(),numero,revendedorId:r.id,itens:comPreco.map(x=>({produtoId:x.p.id,nome:x.p.nome,embalagem:x.p.embalagem,precoUnitario:x.preco,quantidade:x.q})),total,recebimento:manualRec,endereco:manualRec==='entrega'?(r.endereco||'Endereco a confirmar'):'Retirada na empresa',pagamento:manualPag,pagSituacao:'pendente',status:'aguardando_aprovacao',criadoEm:new Date().toISOString(),historico:[{status:'aguardando_aprovacao',em:new Date().toISOString(),por:'EXTRABOM (atendimento)'}]}; updateDb(d=>{ comPreco.forEach(x=>{const pr=d.produtos.find(y=>y.id===x.p.id); if(pr) pr.estoqueReservado+=x.q}); d.pedidos.unshift(pedido); d.notificacoes.unshift(notify(r.id,'Seu pedido '+numero+' foi lancado pela equipe EXTRABOM e aguarda aprovacao.')); return d }); enviarPushRemoto({tipo:'status',alvo:'revendedor',revendedorId:r.id,titulo:'🍦 Pedido '+numero+' lancado para voce',corpo:'A equipe EXTRABOM lancou seu pedido de '+money(total)+'. Acompanhe no app!'}); setManualCart({}); setAdminView('pedidos'); setToast('Pedido '+numero+' lancado para '+r.nome+'!') }
 function criarPedido(){
   if(!rev) return; const faltam=dadosFaltando(rev,recebimento); if(faltam.length){ setToast('Complete seus dados: '+faltam.join(', ')+'.'); setView('perfil'); return } if(faltaMin>0){setToast('Falta '+money(faltaMin)+' para atingir seu pedido mínimo.');return}
   const numero='EXT-'+new Date().getFullYear()+'-'+String(db.pedidos.length+1).padStart(4,'0')
   const pedido:Pedido={id:'ped'+Date.now(),numero,revendedorId:rev.id,itens:cartItens.map(i=>({produtoId:i.p.id,nome:i.p.nome,embalagem:i.p.embalagem,precoUnitario:i.preco,quantidade:i.q})),total:cartTotal,recebimento,endereco:recebimento==='entrega'?rev.endereco:'Retirada na EXTRABOM',pagamento,pagSituacao:'pendente',status:'aguardando_aprovacao',criadoEm:new Date().toISOString(),historico:[{status:'aguardando_aprovacao',em:new Date().toISOString(),por:rev.nome}]}
   updateDb(d=>{ cartItens.forEach(i=>{const p=d.produtos.find(x=>x.id===i.p.id)!; if(p) p.estoqueReservado+=i.q}); d.pedidos.unshift(pedido); d.notificacoes.unshift(notify(rev.id,'Pedido '+numero+' enviado e aguardando aprovação da EXTRABOM.')); d.movimentos.unshift({id:'m'+Date.now(),produto:'Reserva temporária',tipo:'reserva',qtd:cartCount,em:new Date().toISOString(),motivo:'Pedido '+numero}); return d}); enviarPushRemoto({tipo:'novo_pedido',alvo:'admins',revendedorId:rev.id,titulo:'🧾 Novo pedido '+numero,corpo:rev.nome+' enviou um pedido de '+money(cartTotal)+'. Abra a Central de Pedidos.'})
   setCart({}); setSelPedido(pedido); setView('enviado'); setToast('Pedido '+numero+' enviado com sucesso!')
 }
 function mudarStatus(p:Pedido,novo:StatusPedido,motivo=''){
   updateDb(d=>{ const ped=d.pedidos.find(x=>x.id===p.id)!; const antigo=ped.status;
     // baixa de estoque na separação
     if(novo==='separacao_producao' && antigo!=='separacao_producao' && antigo!=='aguardando_conferencia' && antigo!=='pronto'){ ped.itens.forEach(it=>{const pr=d.produtos.find(x=>x.id===it.produtoId); if(pr){pr.estoqueFisico=Math.max(0,pr.estoqueFisico-it.quantidade); pr.estoqueReservado=Math.max(0,pr.estoqueReservado-it.quantidade)}}); d.movimentos.unshift({id:'m'+Date.now(),produto:ped.itens.map(i=>i.nome).join(', '),tipo:'saida_separacao',qtd:ped.itens.reduce((a,i)=>a+i.quantidade,0),em:new Date().toISOString(),motivo:'Separação '+ped.numero}) }
     // libera reserva em recusa/cancelamento antes da separação
     if((novo==='recusado'||novo==='cancelado') && ['aguardando_aprovacao','aprovado'].includes(antigo)){ ped.itens.forEach(it=>{const pr=d.produtos.find(x=>x.id===it.produtoId); if(pr) pr.estoqueReservado=Math.max(0,pr.estoqueReservado-it.quantidade)}) }
     ped.status=novo; if(motivo) ped.motivo=motivo; ped.historico.push({status:novo,em:new Date().toISOString(),por:'Equipe EXTRABOM'});
     d.notificacoes.unshift(notify(ped.revendedorId,'Pedido '+ped.numero+': '+STATUS_LABEL[novo]+(motivo?(' — '+motivo):''))); return d})
   setToast('Pedido '+p.numero+' atualizado: '+STATUS_LABEL[novo]); enviarPushRemoto({tipo:['pronto','saiu_entrega','entregue','retirado'].includes(novo)?'pronto_entrega':'status',alvo:'revendedor',revendedorId:p.revendedorId,titulo:('📦 Pedido '+p.numero),corpo:'Agora esta: '+STATUS_LABEL[novo]+(motivo?(' — '+motivo):'')}); const np={...p,status:novo}; setSelPedido(np)
 }
 function apagarRevendedor(r:any){ const pedidosR=db.pedidos.filter(x=>x.revendedorId===r.id); if(!confirm('Apagar de vez o revendedor '+r.nome+'? Isso nao tem volta.')) return; if(pedidosR.length>0){ if(!confirm('ATENCAO: '+r.nome+' tem '+pedidosR.length+' pedido(s) no historico. Se apagar, os pedidos ficam sem o nome do cliente. Para cliente real, prefira BLOQUEAR. Apagar mesmo assim?')) return } updateDb(d=>{ d.revendedores=d.revendedores.filter(x=>x.id!==r.id); return d }); setToast('Revendedor '+r.nome+' apagado.') }
 function apagarPedido(p:Pedido){ if(!confirm('Apagar o pedido '+p.numero+'? Isso nao tem volta. Para pedidos reais, prefira CANCELAR (fica no historico).')) return; updateDb(d=>{ // devolve estoque conforme a etapa em que o pedido estava
   if(['aguardando_aprovacao','aprovado'].includes(p.status)){ p.itens.forEach(it=>{const pr=d.produtos.find(x=>x.id===it.produtoId); if(pr) pr.estoqueReservado=Math.max(0,pr.estoqueReservado-it.quantidade)}) }
   if(['separacao_producao','aguardando_conferencia','pronto','saiu_entrega'].includes(p.status)){ p.itens.forEach(it=>{const pr=d.produtos.find(x=>x.id===it.produtoId); if(pr) pr.estoqueFisico+=it.quantidade}) }
   d.pedidos=d.pedidos.filter(x=>x.id!==p.id); return d }); setSelPedido(null); setToast('Pedido '+p.numero+' apagado.') }
 function pedirNovamente(p:Pedido){ const c:Record<string,number>={}; p.itens.forEach(i=>{const prod=db.produtos.find(x=>x.id===i.produtoId); if(prod&&prod.ativo&&prod.disponibilidade!=='indisponivel') c[i.produtoId]=i.quantidade}); setCart(c); setView('carrinho'); setToast('Itens carregados com preços e disponibilidade atuais. Confira antes de enviar.') }

 const sairSessao=()=>{ try{ supabase?.auth.signOut() }catch(e){} setSession(null); try{localStorage.removeItem('extrabom_session')}catch(e){} }
 useEffect(()=>{ if(!supabase) return; const {data:ouv}=supabase.auth.onAuthStateChange((ev:string)=>{ if(ev==='PASSWORD_RECOVERY') setModoRecuperar(true) }); return ()=>{ try{ouv?.subscription?.unsubscribe()}catch(e){} } },[])
 useEffect(()=>{ if(!supabase) return; (async()=>{ try{ const lembrar=localStorage.getItem('extrabom_lembrar')!=='0'; if(!lembrar && !sessionStorage.getItem('extrabom_aberta')){ await supabase.auth.signOut(); return } sessionStorage.setItem('extrabom_aberta','1'); const {data}=await supabase.auth.getUser(); const u:any=data?.user; if(u){ const m=u.user_metadata||{}; if(m.role==='admin') setSession({role:'admin'}); else if(m.role==='revendedor') setSession({role:'revendedor',revendedorId:m.revendedorId||'r1'}) } }catch(e){} })() },[])

 async function criarAcesso(){ if(!supabase){setToast('Banco nao conectado.');return} if(!novoAcesso.email||novoAcesso.senha.length<6){setToast('Informe e-mail e senha de 6+ caracteres.');return} try{ const {data: sess}=await supabase.auth.getSession(); const token=sess?.session?.access_token; if(!token){setToast('Entre como administrador novamente.');return} const r=await fetch('/api/criar-acesso',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify(novoAcesso)}); const j=await r.json(); if(!r.ok){setToast(j.erro||'Erro ao criar acesso.');return} setUltimoAcesso({email:novoAcesso.email,senha:novoAcesso.senha,role:novoAcesso.role,revendedorId:novoAcesso.revendedorId}); setNovoAcesso({email:'',senha:'',role:'revendedor',revendedorId:'r1'}); setToast('Acesso criado! Envie o convite pelo WhatsApp.') }catch(e){ setToast('Erro de conexao ao criar acesso.') } }

 if(modoRecuperar){ return <div style={{minHeight:'100dvh',background:'linear-gradient(180deg,#0A2F6B,#0B4DA2)',display:'flex',justifyContent:'center',alignItems:'center',padding:16}}><div style={{...s.card,width:'100%',maxWidth:400}}><div style={{textAlign:'center'}}><img src="/logo.png" style={{height:64,objectFit:'contain'}}/></div><h2 style={{color:MARINHO,textAlign:'center'}}>Criar nova senha</h2><label style={{fontSize:13,fontWeight:700}}>Nova senha (6+ caracteres)</label><input type="password" style={{...s.input,margin:'6px 0 10px'}} value={novaSenha} onChange={e=>setNovaSenha(e.target.value)}/><label style={{fontSize:13,fontWeight:700}}>Repita a nova senha</label><input type="password" style={{...s.input,margin:'6px 0 14px'}} value={confSenha} onChange={e=>setConfSenha(e.target.value)}/><button style={s.btn(VERDE)} onClick={async()=>{ if(novaSenha.length<6){setToast('A senha precisa de 6+ caracteres.');return} if(novaSenha!==confSenha){setToast('As senhas nao conferem.');return} const {error}=await supabase!.auth.updateUser({password:novaSenha}); if(error){setToast('Erro: '+error.message);return} setModoRecuperar(false); setNovaSenha(''); setConfSenha(''); try{await supabase!.auth.signOut()}catch(e){} setSession(null); setToast('Senha alterada! Entre com a nova senha.') }}>Salvar nova senha</button></div>{toast&&<Toast t={toast}/>}</div> }

 async function autocadastrar(){ if(!cad.nome||!cad.negocio||!cad.email.includes('@')||cad.senha.length<6){setToast('Preencha nome, negocio, e-mail e senha de 6+.');return} if(supabase){ try{ const r=await fetch('/api/cadastro-revendedor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(cad)}); const j=await r.json(); if(!r.ok){setToast(j.erro||'Erro no cadastro.');return} const {data,error}=await supabase.auth.signInWithPassword({email:cad.email.trim(),password:cad.senha}); if(!error&&data.user){ setSession({role:'revendedor',revendedorId:j.revendedorId}); setToast('Cadastro enviado! Aguardando liberacao da EXTRABOM.') } else { setModoCadastro(false); setToast('Cadastro enviado! A EXTRABOM vai analisar e liberar seu acesso.') } }catch(e){ setToast('Erro de conexao. Tente de novo.') } } else { const id='r'+Date.now(); updateDb(d=>{d.revendedores.push({id,nome:cad.nome,negocio:cad.negocio,telefone:cad.telefone,doc:cad.doc,endereco:cad.endereco,login:cad.email,ativo:false,pedidoMinimo:0,pagamento:['pix','na_entrega','na_retirada'],precos:{}});return d}); setSession({role:'revendedor',revendedorId:id}); setToast('Cadastro enviado! Aguardando liberacao.') } }

