<div style={{...s.card,marginBottom:14}}><b>➕ Novo insumo</b><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(130px,1fr))',gap:8,marginTop:10}}><input style={s.input} placeholder='Nome (ex.: Leite em po)' value={novoInsumo.nome} onChange={e=>setNovoInsumo({...novoInsumo,nome:e.target.value})}/><select style={s.input} value={novoInsumo.unidade} onChange={e=>setNovoInsumo({...novoInsumo,unidade:e.target.value})}><option>kg</option><option>L</option><option>un</option><option>pct</option><option>cx</option></select><input style={s.input} type='number' placeholder='Estoque minimo' value={novoInsumo.minimo} onChange={e=>setNovoInsumo({...novoInsumo,minimo:e.target.value})}/></div><button style={{...s.btn(VERDE),marginTop:10}} onClick={()=>{ if(!novoInsumo.nome.trim()){setToast('De um nome ao insumo.');return} updateDb(d=>{ d.insumos=d.insumos||[]; d.insumos.push({id:'i'+Date.now(),nome:novoInsumo.nome.trim(),unidade:novoInsumo.unidade,custoMedio:0,estoque:0,estoqueMinimo:Number(novoInsumo.minimo)||0}); return d }); setNovoInsumo({nome:'',unidade:'kg',minimo:'0'}); setToast('Insumo cadastrado! Registre a primeira compra abaixo.') }}>Cadastrar insumo</button></div>
{(db.insumos||[]).map(ins=>{ const c=compraIns[ins.id]||{qtd:'',valor:''}; return <div key={ins.id} style={{...s.card,marginBottom:10}}><div style={{display:'flex',justifyContent:'space-between',flexWrap:'wrap',gap:8}}><b>{ins.nome}</b><span style={s.badge(ins.estoqueMinimo>0&&ins.estoque<=ins.estoqueMinimo?'#DC2626':VERDE)}>Estoque: {Number(ins.estoque.toFixed(2))} {ins.unidade}</span></div><div style={{fontSize:13,color:'#475569'}}>Custo medio: <b>{money(ins.custoMedio)}/{ins.unidade}</b> • Minimo: {ins.estoqueMinimo} {ins.unidade}</div><div style={{display:'flex',gap:8,flexWrap:'wrap',marginTop:10,alignItems:'center'}}><input style={{...s.input,width:110}} type='number' placeholder={'Qtd ('+ins.unidade+')'} value={c.qtd} onChange={e=>setCompraIns({...compraIns,[ins.id]:{...c,qtd:e.target.value}})}/><input style={{...s.input,width:150}} type='number' placeholder='Valor total pago R$' value={c.valor} onChange={e=>setCompraIns({...compraIns,[ins.id]:{...c,valor:e.target.value}})}/><button style={{...s.btn(VERDE),width:'auto',padding:'11px 16px'}} onClick={()=>{ const q=Number(c.qtd)||0, v=Number(c.valor)||0; if(q<=0||v<=0){setToast('Informe quantidade e valor da compra.');return} updateDb(d=>{ const x=(d.insumos||[]).find(i=>i.id===ins.id)!; const novoTotal=x.estoque+q; x.custoMedio=novoTotal>0?((x.estoque*x.custoMedio)+v)/novoTotal:x.custoMedio; x.estoque=novoTotal; d.movInsumos=d.movInsumos||[]; d.movInsumos.unshift({id:'mi'+Date.now(),insumo:ins.nome,tipo:'compra',qtd:q,em:new Date().toISOString(),motivo:'Compra registrada: '+money(v)}); return d }); setCompraIns({...compraIns,[ins.id]:{qtd:'',valor:''}}); setToast('Compra registrada: custo medio atualizado.') }}>🛒 Registrar compra</button><label style={{fontSize:12,fontWeight:700}}>Minimo<input style={{...s.input,width:90,marginLeft:6}} type='number' value={ins.estoqueMinimo} onChange={e=>updateDb(d=>{ const x=(d.insumos||[]).find(i=>i.id===ins.id)!; x.estoqueMinimo=Number(e.target.value)||0; return d })}/></label><button style={{...s.btn('#F59E0B'),width:'auto',padding:'11px 14px'}} onClick={()=>{ const q=Number(c.qtd)||0; if(q<=0){setToast('Informe a quantidade da perda no campo Qtd.');return} if(!confirm('Registrar PERDA de '+q+' '+ins.unidade+' de '+ins.nome+'?')) return; updateDb(d=>{ const x=(d.insumos||[]).find(i=>i.id===ins.id)!; x.estoque=Math.max(0,x.estoque-q); d.movInsumos=d.movInsumos||[]; d.movInsumos.unshift({id:'mi'+Date.now(),insumo:ins.nome,tipo:'perda',qtd:q,em:new Date().toISOString(),motivo:'Perda registrada pelo escritorio'}); return d }); setToast('Perda registrada.') }}>Perda</button></div></div>})}
